// package secretlib.internal;
public class Secret {
    public String hiddenValue() { return "tajna wartosc"; }
}

// package probe;
public class ReflectionProbe {
    public static void main(String[] args) {
        Class<?> secretClass = Class.forName("secretlib.internal.Secret", true, loader);
        Object instance = secretClass.getDeclaredConstructor().newInstance();
        Method method = secretClass.getMethod("hiddenValue");
        System.out.println(method.invoke(instance)); // SUKCES na classpath, BLAD na module path
    }
}

Ten sam, NIEZMIENIONY kod uruchamiamy: raz NA CLASSPATH (-cp) - SUKCES (brak silnej enkapsulacji); raz NA MODULE PATH jako DWA OSOBNE MODULY (secretlib NIE eksportuje/opens swojego pakietu internal) - BLAD dostepu w runtime.

// module-info.java modulu secretlib:
module secretlib {
}

// module-info.java modulu probe:
module probe {
    requires secretlib;
}

// Kompilacja: javac --module-source-path <src> -d <out> --module secretlib,probe
// Uruchomienie: java --module-path <out> --module probe/probe.ReflectionProbe

Modul probe wymaga secretlib (moze go 'czytac'), ale to NIE wystarczy, zeby refleksyjnie dostac sie do nie-eksportowanego pakietu secretlib.internal. Realny blad: IllegalAccessException: 'module secretlib does not open/export secretlib.internal to module probe'.

exercises.solution:
// Modul nienazwany to specjalny 'kontener' w JPMS, do ktorego trafia CALY kod uruchamiany
// na klasycznym CLASSPATH (nie module path). Czyta kazdy inny modul i eksportuje wszystkie
// swoje pakiety kazdemu - dziala dokladnie jak classpath sprzed Javy 9, bez enkapsulacji.
// javaQuest w nim zyje, bo caly kurs jest kompilowany i uruchamiany bez module-info.java -
// swiadoma decyzja, zeby zachowac jedna, plaska przestrzen pakietow miedzy lekcjami.

// Split package to sytuacja, gdy DWA (lub wiecej) roznych JAR-ow/katalogow definiuja klasy
// w TYM SAMYM pakiecie (np. com.example.util). Na classpath jest to MOZLIWE, bo JVM nie
// prowadzi zadnej ksiegowosci 'ktory JAR jest wlascicielem ktorego pakietu' - Application
// Class Loader po prostu laduje pierwsza pasujaca klase znaleziona wedlug kolejnosci
// wpisow na classpath. To RYZYKOWNE, bo ktora wersja klasy 'wygra' zalezy od przypadkowej
// kolejnosci JAR-ow, dajac trudne do zdiagnozowania, niedeterministyczne bledy.

Path workDir = Files.createTempDirectory("ex04");
Files.writeString(workDir.resolve("Simple.java"), "public class Simple { public static void main(String[] a) { System.out.println(\"dziala\"); } }");
String javac = System.getProperty("java.home") + File.separator + "bin" + File.separator + "javac";
String java = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
new ProcessBuilder(javac, workDir.resolve("Simple.java").toString()).inheritIO().start().waitFor(10, TimeUnit.SECONDS);
new ProcessBuilder(java, "-cp", workDir.toString(), "Simple").inheritIO().start().waitFor(10, TimeUnit.SECONDS);

// 'exports pkg;' udostepnia PUBLICZNE typy pakietu innym modulom w compile-time, ale NIE
// daje uprawnien do DEEP REFLECTION (setAccessible(true) na prywatnych skladowych) -
// proba takiej refleksji wciaz zakonczy sie InaccessibleObjectException.
// 'opens pkg;' dodaje WLASNIE to dodatkowe uprawnienie - pozwala frameworkom (Hibernate,
// Jackson, Spring) refleksyjnie modyfikowac prywatne pola/metody. Modul MOZE miec exports
// bez opens (widocznosc typow bez deep reflection) albo opens bez exports (deep reflection
// bez widocznosci w compile-time) - to dwa niezalezne uprawnienia.

// --module-path wymaga module-info.java (lub .class), bo to WLASNIE ten plik deklaruje
// GRANICE modulu (jakie pakiety eksportuje, czego wymaga) - bez niego JVM nie ma zadnej
// informacji potrzebnej do zbudowania GRAFU CZYTELNOSCI miedzy modulami. -cp/-classpath
// nie ma takiego wymogu, bo classpath traktuje wszystko jako plaski, jednolity zbior
// klas bez zadnej deklarowanej struktury/granic - kazda klasa jest po prostu 'gdzies tam'.

System.out.printf("%-30s | %-15s | %-15s%n", "Cecha", "classpath", "module path");
System.out.printf("%-30s | %-15s | %-15s%n", "Silna enkapsulacja", "NIE", "TAK");
System.out.printf("%-30s | %-15s | %-15s%n", "Split packages", "mozliwe", "zabronione");
System.out.printf("%-30s | %-15s | %-15s%n", "Wykrywanie braku zaleznosci", "runtime", "start (przy budowie grafu)");
System.out.printf("%-30s | %-15s | %-15s%n", "Wymog module-info", "NIE", "TAK");

static int runProcess(String... command) throws Exception {
    ProcessBuilder pb = new ProcessBuilder(command);
    pb.redirectErrorStream(true);
    Process p = pb.start();
    System.out.print(new String(p.getInputStream().readAllBytes()));
    boolean finished = p.waitFor(10, TimeUnit.SECONDS);
    if (!finished) { p.destroyForcibly(); return -1; }
    return p.exitValue();
}

String javaExe = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
System.out.println("Kod wyjscia: " + runProcess(javaExe, "-version"));

// Analogiczne do writeSecretSource/writeProbeSource z teorii, ale bez module-info.java
// Kompilacja: javac -d out pkg1/A.java pkg2/B.java
// Uruchomienie: java -cp out pkg2.B
// Oczekiwany wynik: SUKCES refleksji, kod wyjscia 0 - brak enkapsulacji na classpath.

// module a { exports pkg.a; } - klasa Foo w pkg.a
// module b { requires a; } - Main uzywajacy Foo
// javac --module-source-path <src> -d <out> --module a,b
// java --module-path <out> --module b/pkg.b.Main
// Kod wyjscia oczekiwany: 0

// module a { } // BRAK exports
// module b { requires a; } - Main.java: import pkg.a.Foo; // BLAD
// javac zglosi: error: package pkg.a is not visible
// (package pkg.a is declared in module a, which does not export it)

// Ten sam kod co runModulePathVariant() z teorii - Secret w secretlib.internal (NIE
// eksportowany), ReflectionProbe w module probe probujacy refleksyjnie do niego dotrzec.
// Output podprocesu zawiera: BLAD refleksji: IllegalAccessException - module secretlib
// does not open secretlib.internal to module probe

// module secretlib { opens secretlib.internal; }
// Po tej zmianie i przekompilowaniu, ReflectionProbe.main() wypisuje:
// SUKCES refleksji: tajna wartosc z pakietu 'secretlib.internal'
// Kod wyjscia: 0

int[] exitCodes = new int[2];
exitCodes[0] = runClasspathVariantExitCode();
exitCodes[1] = runModulePathVariantExitCode();
System.out.printf("%-15s | %s%n", "classpath", exitCodes[0]);
System.out.printf("%-15s | %s%n", "module path", exitCodes[1]);

// module a { opens pkg.a to b; }
// module b { requires a; } - refleksja SIE UDAJE
// module c { requires a; } - refleksja NIE UDAJE SIE (c nie jest na liscie 'to')
// Uruchomienie b/Main -> sukces; uruchomienie c/Main -> InaccessibleObjectException

// module mod1 { exports shared; } - klasa shared.ClassA
// module mod2 { exports shared; } - klasa shared.ClassB
// java --module-path <mod1>;<mod2> --module mod1/... zglosi PRZY STARCIE blad:
// "module mod1 and module mod2 export package shared to module ..." (split package)

// Na CLASSPATH: refleksyjny dostep do 'ukrytego' pakietu NIE JEST WYKRYWANY jako blad -
// po prostu dziala, bo nie ma zadnej enkapsulacji do naruszenia.
// Na MODULE PATH z bezposrednim importem: blad wykrywany JUZ PRZY KOMPILACJI
// ('package X is not visible') - najwczesniejszy mozliwy moment.
// Na MODULE PATH z refleksja: blad wykrywany DOPIERO W RUNTIME (InaccessibleObjectException),
// bo Class.forName po nazwie omija sprawdzanie kompilatora - ale WCIAZ jest wykrywany,
// w przeciwienstwie do classpath, gdzie w ogole nie ma takiej kontroli.

// Zbuduj plik 'mylib-1.0.jar' (bez module-info) zawierajacy klase mylib.Helper
// module app { requires mylib; } // 'mylib' to nazwa automatycznego modulu z pliku JAR
// java --module-path <out>;mylib-1.0.jar --module app/app.Main
// Automatyczna nazwa 'mylib' pochodzi z nazwy pliku 'mylib-1.0.jar' (bez wersji/rozszerzenia)

record Result(String wariant, int exitCode, String skrocone) {}
List<Result> results = new ArrayList<>();
results.add(new Result("classpath", cpExit, cpOutput.length() > 60 ? cpOutput.substring(0, 60) : cpOutput));
results.add(new Result("module path", mpExit, mpOutput.length() > 60 ? mpOutput.substring(0, 60) : mpOutput));
System.out.println("=== RAPORT ===");
results.forEach(r -> System.out.println(r.wariant() + ": exit=" + r.exitCode() + ", " + r.skrocone()));

enum Visibility { NONE, EXPORTS, OPENS }

static String moduleInfoFor(Visibility v) {
    return switch (v) {
        case NONE -> "module secretlib { }";
        case EXPORTS -> "module secretlib { exports secretlib.internal; }";
        case OPENS -> "module secretlib { opens secretlib.internal; }";
    };
}

for (Visibility v : Visibility.values()) {
    // wygeneruj module-info.java z tresciaa moduleInfoFor(v), skompiluj, uruchom
    System.out.println(v + " -> refleksja udana: " + (v == Visibility.OPENS));
}

// class Secret { private String secretMethod() { return "tajne"; } }
// module secretlib { exports secretlib.internal; } // BEZ opens
// getDeclaredMethod("secretMethod").setAccessible(true) -> InaccessibleObjectException
//
// module secretlib { opens secretlib.internal; }
// TO SAMO wywolanie -> dziala poprawnie, zwraca "tajne"

// module a { exports pkg.a; }
// module b { requires transitive a; exports pkg.b; }
// module c { requires b; } // BEZ requires a!
// Kod w C uzywajacy typu z pkg.a KOMPILUJE SIE POPRAWNIE dzieki 'requires transitive' w B -
// C 'dziedziczy' czytelnosc modulu a automatycznie.

// Krok 1: classpath, bez module-info.java - refleksja DZIALA
// Krok 2: DOKLADNIE ten sam kod klas, ale dodajemy plik module-info.java:
// module app { } // pusty, zero exports
// Uruchomienie jako modul --module-path -> refleksja PRZESTAJE DZIALAC
// (InaccessibleObjectException), mimo ZE ani jedna linia logiki biznesowej sie nie zmienila -
// jedyna roznica to sposob URUCHOMIENIA (classpath vs module path) i obecnosc deskryptora.

System.out.println("=== KATALOG BLEDOW JPMS ===");
System.out.println("1. Brak exports (refleksja): IllegalAccessException/InaccessibleObjectException");
System.out.println("2. exports bez opens + setAccessible: InaccessibleObjectException");
System.out.println("3. Split package: blad przy STARCIE JVM, nie w trakcie dzialania");
// Kazdy z tych scenariuszy uruchomiony realnie (jak w Zadaniach 14-18) daje SPECYFICZNY,
// odrebny komunikat bledu, mimo ze wszystkie dotycza tego samego tematu 'silnej enkapsulacji'.

// Migracja duzego, istniejacego projektu do JPMS wymaga PRZEMYSLENIA i JAWNEGO zadeklarowania
// granic KAZDEGO modulu (co eksportuje, czego wymaga) - dla projektow z tysiacami klas i
// setkami wzajemnych zaleznosci to ogromny, czasochlonny wysilek migracyjny. javaQuest jest
// tego przykladem: kurs jest zaprojektowany jako JEDNA, plaska przestrzen pakietow, w ktorej
// kursant swobodnie 'przeskakuje' miedzy lekcjami (odwolania w komentarzach, wspolne wzorce) -
// silna enkapsulacja wymuszalaby jawne exports/requires miedzy KAZDA para pakietow lekcji,
// zaprzeczajac idei jednego, spojnego projektu. Wiele bibliotek/frameworkow (jak Spring Boot)
// takze WCIAZ zaklada dzialanie na classpath, wiec migracja aplikacji koncowej czesto nie
// przynosi realnych korzysci proporcjonalnych do kosztu.

// mylib-1.0.jar (bez module-info) na module-path -> automatyczny modul 'mylib'
// module app { requires mylib; }
// javac --module-source-path <src> --module-path <jarDir> -d <out> --module app
// java --module-path <out>;<jarDir> --module app/app.Main
System.out.println("Nazwa automatycznego modulu wyprowadzona z pliku: mylib-1.0.jar -> mylib");

long[] cpTimes = new long[3];
long[] mpTimes = new long[3];
for (int i = 0; i < 3; i++) {
    long t1 = System.nanoTime();
    runProcess(javaExe, "-cp", cpOutDir.toString(), "Hello");
    cpTimes[i] = System.nanoTime() - t1;

    long t2 = System.nanoTime();
    runProcess(javaExe, "--module-path", mpOutDir.toString(), "--module", "hello/hello.Main");
    mpTimes[i] = System.nanoTime() - t2;
}
System.out.println("Sredni czas classpath: " + java.util.Arrays.stream(cpTimes).average().orElse(0) / 1_000_000 + " ms");
System.out.println("Sredni czas module path: " + java.util.Arrays.stream(mpTimes).average().orElse(0) / 1_000_000 + " ms");
// Wniosek: dla prostych programow roznica jest zazwyczaj niewielka/statystycznie nieistotna.

record AuditResult(String wariant, int exitCode, boolean reflectionSucceeded, String errorSnippet) {}
List<AuditResult> results = new ArrayList<>();
// dla kazdego z 4 wariantow: skompiluj, uruchom, zapisz wynik
results.add(new AuditResult("classpath", 0, true, ""));
results.add(new AuditResult("modul zamkniety", 1, false, "InaccessibleObjectException"));
results.add(new AuditResult("modul exports", 1, false, "InaccessibleObjectException (setAccessible)"));
results.add(new AuditResult("modul opens", 0, true, ""));

System.out.println("=== RAPORT AUDYTU ===");
results.forEach(r -> System.out.printf("%-20s | exit=%d | refleksja=%b | %s%n", r.wariant(), r.exitCode(), r.reflectionSucceeded(), r.errorSnippet()));
